import{z as A,x as p,o,c as C,q as s,j as i,D as t,d as r,s as l,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"OCC","description":"","frontmatter":{"title":"OCC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/occ.md","filePath":"cs/occ.md","lastUpdated":1791063341000}'),d={name:"cs/occ.md"};function B(c,a,m,u,b,h){const n=p("Mermaid");return o(),C("div",null,[a[2]||(a[2]=s('<h1 id="occ" tabindex="-1">OCC <a class="header-anchor" href="#occ" aria-label="Permalink to &quot;OCC&quot;">​</a></h1><div class="epigraph"><p>乐观并发：工作阶段不锁（或极少锁），提交时比较读集版本；冲突则 abort。低争用时吞吐高，高争用时重试打满 CPU。</p><footer>—— 据 Kung and Robinson, On Optimistic Methods for Concurrency Control, TODS 1981；Gray；Hekaton</footer></div><p><a href="/cs/timestamp-ordering">上一课</a>在访问时按戳拒绝。本课把检查推迟到提交：乐观并发控制（OCC）。主干锁课偏悲观；进阶补乐观轴。SSI 下一课在快照上再加写偏斜检测。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>读阶段：事务拷贝或直接读已提交数据，记读集版本号。写阶段：写私有缓冲。验证：读集版本是否仍等于开始时，写集是否与并发提交冲突。完成：安装写集、分配提交戳。缺口是<strong>验证串行化</strong>：验证阶段通常短锁或单线程 stamp，否则验证本身乱序。</p><p>Kung-Robinson 三阶段。现代主存库（Hekaton）用 OCC+MVCC：读可见版本，提交 CAS 安装。争用高则 abort 率高，要指数退避或回退 2PL。</p><p><span class="marginnote">Kung and Robinson, TODS 1981。乐观不是「不管隔离」。丢失更新在验证失败时 abort，不会静默覆盖——除非实现漏读集。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读集/写集粒度：行或页。粒度粗冲突多，细则记更多。只读事务可跳验证若快照不变（后课只读快照）。混合：热点行悲观，其余乐观。</p><p>与 WAL：验证通过后仍先日志再安装，steal 规则不变。OCC 不管持久，管并发。</p><p><span class="marginnote">术语翻译：读集就是「这个事务看过哪些数据、当时版本号是多少」的清单，写集是「改过哪些、改成什么」的清单。验证像超市小票对账——把读集清单逐行核对价签（版本号），只要有一条变了，整单重来。</span></p>',11)),(o(),i(E,null,{default:t(()=>[l(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RD%5B%22%E8%AF%BB%E9%98%B6%E6%AE%B5%E8%AE%B0%E7%89%88%E6%9C%AC%22%5D%20--%3E%20WR%5B%22%E5%86%99%E7%A7%81%E6%9C%89%E7%BC%93%E5%86%B2%22%5D%0A%20%20WR%20--%3E%20VAL%5B%22%E9%AA%8C%E8%AF%81%E8%AF%BB%E9%9B%86%22%5D%0A%20%20VAL%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20INS%5B%22%E5%AE%89%E8%A3%85%E5%86%99%E9%9B%86%22%5D%0A%20%20VAL%20--%3E%7C%22%E5%A4%B1%E8%B4%A5%22%7C%20AB%5B%22abort%20%E9%87%8D%E8%AF%95%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"幻读：读集若只有行不管「范围内新插入」，会漏冲突——要谓词锁、间隙或扫描完整范围进读集。这是 OCC 的经典缝，间隙锁课再补悲观侧。",-1)),a[5]||(a[5]=e("p",null,"高争用时 abort 会滚雪球，这正是「乐观在高争用下崩」的机制：",-1)),(o(),i(E,null,{default:t(()=>[l(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22100%20%E4%B8%AA%E4%BA%8B%E5%8A%A1%E6%8A%A2%E5%90%8C%E4%B8%80%E7%83%AD%E7%82%B9%E8%A1%8C%22%5D%20--%3E%20VAL%5B%22%E5%90%8C%E6%97%B6%E8%BF%9B%E5%85%A5%E9%AA%8C%E8%AF%81%22%5D%0A%20%20VAL%20--%3E%7C%22%E4%BB%85%201%20%E4%B8%AA%E9%80%9A%E8%BF%87%22%7C%20OK%5B%22%E6%8F%90%E4%BA%A4%E6%88%90%E5%8A%9F%22%5D%0A%20%20VAL%20--%3E%7C%22%E5%85%B6%E4%BD%99%2099%20%E4%B8%AA%E5%A4%B1%E8%B4%A5%22%7C%20AB%5B%22abort%20%E5%90%8E%E9%87%8D%E8%AF%95%22%5D%0A%20%20AB%20--%3E%20VAL%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">数字实例：100 个事务抢一行，验证一轮只有 1 个成功、99 个 abort；若每个重试周期约 10 ms，一轮就白烧约 1 秒 CPU，且失败者马上又挤进下一轮验证。争用越高浪费越多——这正是混合策略里「热点行走悲观锁」的动机。</span></p><p>计划：OCC 不改查询计划，但长扫描读集巨大，验证贵，分析查询常不用纯 OCC。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 SSI 的 rw-conflict 图。也不把乐观当成无 WAL。Calvin 后课用确定性排序避免验证。</p><p>后课默认：低争用 OLTP 可用 OCC；验证必须覆盖幻象。SSI：在 SI 上检测写偏斜，接近可串行。</p><p>乐观把阻塞换成 abort。没有免费的可串行。</p><p><span class="marginnote">常见误区：初学者容易以为「乐观 = 不加锁 = 永远更快」。实际上 OCC 只是把等待换成了事后重试：冲突率低时它省掉加锁开销、吞吐更高；冲突率高时 abort 风暴的成本远超一次行锁等待。选型看争用率，不看信仰。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OCC 三阶段：读、验证、安装；失败重试。</li><li>读集必须大到能抓住幻象。</li><li>SSI 下一课：快照隔离上的可串行补丁。</li><li>出处：Kung and Robinson 1981；Gray；Hekaton。</li></ul>',9))])}const S=A(d,[["render",B]]);export{_ as __pageData,S as default};
